// Package canvas is a fixed-size, 16-color pixel grid.
//
// It holds no chain state and knows nothing about payments: the realm
// gno.land/r/g19t6f4f4ptt3m949jznalfsx2h8aj696llul0nj/million/v0 wraps it with pricing and access control.
//
// Storage layout: one []byte per row, allocated on first paint. A row that
// was never painted is nil and costs nothing. Each byte holds a palette
// index; Blank (0) means "never painted".
package canvas

import (
	"errors"
	"strconv"
	"strings"
)

const (
	// Blank is the color of a pixel nobody painted. It cannot be painted.
	Blank byte = 0
	// MaxColor is the highest valid palette index.
	MaxColor byte = 15
	// MaxSide bounds width and height so x*y fits comfortably in an int.
	MaxSide = 10000
)

// Palette maps a color index to its CSS hex value. Index 0 is Blank and is
// rendered as white by clients.
var Palette = [MaxColor + 1]string{
	"#ffffff", // 0 blank
	"#ffffff", // 1 white
	"#e4e4e4", // 2 light gray
	"#888888", // 3 gray
	"#222222", // 4 black
	"#ffa7d1", // 5 pink
	"#e50000", // 6 red
	"#e59500", // 7 orange
	"#a06a42", // 8 brown
	"#e5d900", // 9 yellow
	"#94e044", // 10 lime
	"#02be01", // 11 green
	"#00d3dd", // 12 cyan
	"#0083c7", // 13 blue
	"#cf6ee4", // 14 magenta
	"#820080", // 15 purple
}

var (
	ErrOutOfRange   = errors.New("canvas: pixel out of range")
	ErrInvalidColor = errors.New("canvas: color must be between 1 and 15")
	ErrBadPixel     = errors.New("canvas: pixel must be x,y,color")
)

// Pixel is one paint request.
type Pixel struct {
	X, Y  int
	Color byte
}

// Canvas is a width x height grid of palette indexes.
type Canvas struct {
	width, height int
	rows          [][]byte
	painted       int
}

// New returns an empty canvas. It panics on a non-positive or oversized side.
func New(width, height int) *Canvas {
	if width <= 0 || height <= 0 || width > MaxSide || height > MaxSide {
		panic("canvas: width and height must be between 1 and " + strconv.Itoa(MaxSide))
	}
	return &Canvas{
		width:  width,
		height: height,
		rows:   make([][]byte, height),
	}
}

func (c *Canvas) Width() int  { return c.width }
func (c *Canvas) Height() int { return c.height }

// Painted is the number of pixels that are not Blank.
func (c *Canvas) Painted() int { return c.painted }

// Check reports whether p can be painted on this canvas.
func (c *Canvas) Check(p Pixel) error {
	if p.X < 0 || p.Y < 0 || p.X >= c.width || p.Y >= c.height {
		return ErrOutOfRange
	}
	if p.Color == Blank || p.Color > MaxColor {
		return ErrInvalidColor
	}
	return nil
}

// Get returns the color at (x, y). Out-of-range coordinates panic.
func (c *Canvas) Get(x, y int) byte {
	if x < 0 || y < 0 || x >= c.width || y >= c.height {
		panic(ErrOutOfRange)
	}
	row := c.rows[y]
	if row == nil {
		return Blank
	}
	return row[x]
}

// Set paints p. It panics when Check(p) fails.
func (c *Canvas) Set(p Pixel) {
	if err := c.Check(p); err != nil {
		panic(err)
	}
	row := c.rows[p.Y]
	if row == nil {
		row = make([]byte, c.width)
		c.rows[p.Y] = row
	}
	if row[p.X] == Blank {
		c.painted++
	}
	row[p.X] = p.Color
}

// Rows encodes rows [from, to) as one hex digit per pixel, row after row,
// with no separator. Clients slice it with the known width.
func (c *Canvas) Rows(from, to int) string {
	if from < 0 || to > c.height || from > to {
		panic(ErrOutOfRange)
	}
	var sb strings.Builder
	sb.Grow((to - from) * c.width)
	for y := from; y < to; y++ {
		row := c.rows[y]
		if row == nil {
			for x := 0; x < c.width; x++ {
				sb.WriteByte('0')
			}
			continue
		}
		for _, color := range row {
			sb.WriteByte(hexDigit(color))
		}
	}
	return sb.String()
}

// ParsePixels decodes "x,y,color;x,y,color;...". A trailing ';' is allowed.
// It validates the syntax and the color range but not the coordinates,
// which depend on the canvas: call Check for that.
func ParsePixels(s string) ([]Pixel, error) {
	s = strings.TrimSuffix(s, ";")
	if s == "" {
		return nil, ErrBadPixel
	}
	parts := strings.Split(s, ";")
	pixels := make([]Pixel, 0, len(parts))
	for _, part := range parts {
		fields := strings.Split(part, ",")
		if len(fields) != 3 {
			return nil, ErrBadPixel
		}
		x, err := strconv.Atoi(fields[0])
		if err != nil {
			return nil, ErrBadPixel
		}
		y, err := strconv.Atoi(fields[1])
		if err != nil {
			return nil, ErrBadPixel
		}
		color, err := ParseColor(fields[2])
		if err != nil {
			return nil, err
		}
		pixels = append(pixels, Pixel{X: x, Y: y, Color: color})
	}
	return pixels, nil
}

// ParseColor converts a decimal color index, rejecting Blank.
func ParseColor(s string) (byte, error) {
	n, err := strconv.Atoi(s)
	if err != nil || n <= int(Blank) || n > int(MaxColor) {
		return 0, ErrInvalidColor
	}
	return byte(n), nil
}

// Encode is the inverse of ParsePixels.
func Encode(pixels []Pixel) string {
	var sb strings.Builder
	for i, p := range pixels {
		if i > 0 {
			sb.WriteByte(';')
		}
		sb.WriteString(strconv.Itoa(p.X))
		sb.WriteByte(',')
		sb.WriteString(strconv.Itoa(p.Y))
		sb.WriteByte(',')
		sb.WriteString(strconv.Itoa(int(p.Color)))
	}
	return sb.String()
}

func hexDigit(v byte) byte {
	if v < 10 {
		return '0' + v
	}
	return 'a' + v - 10
}

package canvas

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestNewRejectsBadSizes(t *testing.T) {
	for _, tc := range []struct{ w, h int }{{0, 1}, {1, 0}, {-1, 1}, {MaxSide + 1, 1}, {1, MaxSide + 1}} {
		func() {
			defer func() {
				if r := recover(); r == nil {
					t.Errorf("New(%d, %d) did not panic", tc.w, tc.h)
				}
			}()
			New(tc.w, tc.h)
		}()
	}
}

func TestSetGet(t *testing.T) {
	c := New(4, 3)
	uassert.Equal(t, 4, c.Width())
	uassert.Equal(t, 3, c.Height())
	uassert.Equal(t, 0, c.Painted())
	uassert.Equal(t, Blank, c.Get(3, 2))

	c.Set(Pixel{X: 3, Y: 2, Color: 6})
	uassert.Equal(t, byte(6), c.Get(3, 2))
	uassert.Equal(t, 1, c.Painted())

	// Repainting the same pixel does not count twice.
	c.Set(Pixel{X: 3, Y: 2, Color: 7})
	uassert.Equal(t, byte(7), c.Get(3, 2))
	uassert.Equal(t, 1, c.Painted())

	// Other rows stay unallocated and blank.
	uassert.Equal(t, Blank, c.Get(0, 0))
	uassert.True(t, c.rows[0] == nil, "row 0 should stay nil")
}

func TestCheck(t *testing.T) {
	c := New(2, 2)
	tests := []struct {
		name string
		p    Pixel
		err  error
	}{
		{"ok", Pixel{0, 0, 1}, nil},
		{"ok max", Pixel{1, 1, MaxColor}, nil},
		{"x negative", Pixel{-1, 0, 1}, ErrOutOfRange},
		{"y negative", Pixel{0, -1, 1}, ErrOutOfRange},
		{"x too big", Pixel{2, 0, 1}, ErrOutOfRange},
		{"y too big", Pixel{0, 2, 1}, ErrOutOfRange},
		{"blank color", Pixel{0, 0, Blank}, ErrInvalidColor},
		{"color too big", Pixel{0, 0, MaxColor + 1}, ErrInvalidColor},
	}
	for _, tc := range tests {
		got := c.Check(tc.p)
		if got != tc.err {
			t.Errorf("%s: got %v, want %v", tc.name, got, tc.err)
		}
	}
}

func TestRows(t *testing.T) {
	c := New(3, 3)
	uassert.Equal(t, "000000000", c.Rows(0, 3))
	c.Set(Pixel{X: 1, Y: 1, Color: 15})
	c.Set(Pixel{X: 2, Y: 2, Color: 10})
	uassert.Equal(t, "000", c.Rows(0, 1))
	uassert.Equal(t, "0f0", c.Rows(1, 2))
	uassert.Equal(t, "0f000a", c.Rows(1, 3))
	uassert.Equal(t, "", c.Rows(2, 2))

	for _, r := range [][2]int{{-1, 1}, {0, 4}, {2, 1}} {
		func() {
			defer func() {
				if rec := recover(); rec == nil {
					t.Errorf("Rows(%d, %d) did not panic", r[0], r[1])
				}
			}()
			c.Rows(r[0], r[1])
		}()
	}
}

func TestParsePixels(t *testing.T) {
	px, err := ParsePixels("0,0,1;5,7,15;")
	uassert.NoError(t, err)
	uassert.Equal(t, 2, len(px))
	if px[0] != (Pixel{0, 0, 1}) || px[1] != (Pixel{5, 7, 15}) {
		t.Errorf("unexpected pixels: %v", px)
	}

	for _, bad := range []string{"", ";", "1,2", "1,2,3,4", "a,2,3", "1,b,3", "1,2,c", "1,2,0", "1,2,16", "1,2,-1"} {
		if _, err := ParsePixels(bad); err == nil {
			t.Errorf("ParsePixels(%q) accepted invalid input", bad)
		}
	}
}

func TestEncodeRoundTrip(t *testing.T) {
	in := []Pixel{{0, 0, 1}, {999, 999, 15}, {3, 4, 8}}
	s := Encode(in)
	uassert.Equal(t, "0,0,1;999,999,15;3,4,8", s)
	out, err := ParsePixels(s)
	uassert.NoError(t, err)
	uassert.Equal(t, len(in), len(out))
	for i := range in {
		if in[i] != out[i] {
			t.Errorf("pixel %d: got %v, want %v", i, out[i], in[i])
		}
	}
}

// Package million is a pay-per-pixel collaborative canvas: anyone can paint
// any pixel of a Width x Height grid in one of 15 colors by sending exactly
// Price() ugnot per pixel along with the call. Pixels can be repainted by
// anyone, for the same price. Payments are forwarded to the admin wallet
// as they arrive, and the admin paints for free.
//
// The grid logic lives in gno.land/p/g19t6f4f4ptt3m949jznalfsx2h8aj696llul0nj/canvas/v0; this realm adds the
// payment guard, the owner controls and the read API used by the web client.
package million

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/g19t6f4f4ptt3m949jznalfsx2h8aj696llul0nj/canvas/v0"
	"gno.land/p/nt/ufmt/v0"
)

const (
	// Width and Height are fixed for the life of this version: changing
	// them would change the storage layout, so it means a new /vN.
	// 1250 x 800 is one million pixels in a 16:10 laptop aspect ratio.
	Width  = 1250
	Height = 800

	// DefaultMaxBatch bounds a single PaintBatch call so one tx cannot blow
	// the block gas limit or overflow the price arithmetic. The owner can
	// change it at runtime with SetMaxBatch, up to HardMaxBatch.
	DefaultMaxBatch = 5000
	HardMaxBatch    = 20000

	// DefaultPrice is the initial price per pixel, in ugnot (0.05 GNOT).
	DefaultPrice int64 = 50_000

	// DefaultAdmin receives every payment, paints for free and holds the
	// owner controls. Change it before deploying; TransferOwnership moves
	// it afterwards.
	DefaultAdmin = "g19t6f4f4ptt3m949jznalfsx2h8aj696llul0nj"

	Denom = "ugnot"
)

var (
	board    = canvas.New(Width, Height)
	price    = DefaultPrice
	maxBatch = DefaultMaxBatch
	owner    = address(DefaultAdmin)

	// Stats.
	revenue int64 // total ugnot ever paid for pixels
	paints  int64 // number of successful Paint/PaintBatch calls

	// Change tracking, so clients fetch only the rows that moved.
	// version bumps once per successful paint call; rowVersion holds the
	// version of the last paint that touched each row (0 = never painted).
	version    int64
	rowVersion = make([]int64, Height)
)

// Paint colors one pixel. Send exactly Price() ugnot (nothing for the admin).
func Paint(cur realm, x, y, color int) {
	if color <= 0 || color > int(canvas.MaxColor) {
		panic(canvas.ErrInvalidColor)
	}
	paint([]canvas.Pixel{{X: x, Y: y, Color: byte(color)}}, cur)
}

// PaintBatch colors up to MaxBatchSize() pixels in one call. The argument is
// "x,y,color;x,y,color;...". Send exactly Price() * count ugnot (nothing
// for the admin).
func PaintBatch(cur realm, pixels string) {
	px, err := canvas.ParsePixels(pixels)
	if err != nil {
		panic(err)
	}
	paint(px, cur)
}

// paint takes the realm as its LAST parameter on purpose: a realm first
// parameter would make it a crossing function and Previous() would then
// be this realm instead of the user.
func paint(px []canvas.Pixel, rlm realm) {
	if !rlm.IsCurrent() {
		panic("spoofed realm")
	}
	// Payment guard: unsafe.OriginSend() describes the coins attached to
	// the transaction, which only provably landed here when the caller is
	// a plain user call (no intermediate or ephemeral realm). Keep the two
	// checks together. unsafe is imported for OriginSend only; caller
	// identity always comes from the realm handle.
	if !rlm.Previous().IsUserCall() {
		panic("must be called directly by a user (maketx call)")
	}
	painter := rlm.Previous().Address()
	n := len(px)
	if n == 0 {
		panic("nothing to paint")
	}
	if n > maxBatch {
		panic(ufmt.Sprintf("too many pixels: %d > %d", n, maxBatch))
	}
	for _, p := range px {
		if err := board.Check(p); err != nil {
			panic(err)
		}
	}

	cost := price * int64(n)
	if painter == owner {
		cost = 0 // the admin paints for free
	}
	if sent := sentUgnot(unsafe.OriginSend()); sent != cost {
		panic(ufmt.Sprintf("must send exactly %d%s for %d pixel(s), got %d%s", cost, Denom, n, sent, Denom))
	}
	if cost > 0 {
		// Forward the payment to the admin right away, so nothing
		// accumulates in the realm. BankerTypeOriginSend can only move
		// what this very message sent, which is exactly cost.
		bnk := banker.NewBanker(banker.BankerTypeOriginSend, rlm)
		bnk.SendCoins(rlm.Address(), owner, chain.NewCoins(chain.NewCoin(Denom, cost)))
	}

	version++
	for _, p := range px {
		board.Set(p)
		rowVersion[p.Y] = version
	}
	revenue += cost
	paints++

	// The pixel list itself is not emitted: event attribute values are
	// size-capped by the node and a full batch exceeds it. Clients re-read
	// Rows() after a paint.
	chain.Emit("Paint",
		"painter", painter.String(),
		"count", strconv.Itoa(n),
		"paid", strconv.Itoa(int(cost))+Denom,
	)
}

// sentUgnot returns the ugnot amount in coins and rejects any other denom,
// so a caller cannot pay with something the realm does not price.
func sentUgnot(coins chain.Coins) int64 {
	var amount int64
	for _, c := range coins {
		if c.Denom != Denom {
			panic("only " + Denom + " is accepted")
		}
		amount += c.Amount
	}
	return amount
}

// --- owner controls ---

// assertOwner panics unless the verified caller behind rlm is the owner.
// The realm is deliberately not the first parameter (see paint); the
// leading blank int is the same idiom gno.land/p/nt/ownable uses.
func assertOwner(_ int, rlm realm) {
	if !rlm.IsCurrent() {
		panic("spoofed realm")
	}
	if rlm.Previous().Address() != owner {
		panic("owner only")
	}
}

// SetPrice changes the price per pixel, in ugnot. Zero makes painting free
// for everyone.
func SetPrice(cur realm, ugnot int64) {
	assertOwner(0, cur)
	if ugnot < 0 {
		panic("price must not be negative")
	}
	price = ugnot
}

// SetMaxBatch changes the maximum pixels per PaintBatch call, 1..HardMaxBatch.
func SetMaxBatch(cur realm, n int) {
	assertOwner(0, cur)
	if n < 1 || n > HardMaxBatch {
		panic(ufmt.Sprintf("max batch must be between 1 and %d", HardMaxBatch))
	}
	maxBatch = n
}

// Withdraw sends amount ugnot held by the realm to the given address.
// Payments are forwarded on arrival, so this only matters for coins sent
// to the realm outside of a paint call.
func Withdraw(cur realm, to address, amount int64) {
	assertOwner(0, cur)
	if !to.IsValid() {
		panic("invalid address")
	}
	if amount <= 0 {
		panic("amount must be positive")
	}
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin(Denom, amount)))
}

// TransferOwnership hands the admin role (payments, free painting and the
// owner controls) to newOwner.
func TransferOwnership(cur realm, newOwner address) {
	assertOwner(0, cur)
	if !newOwner.IsValid() {
		panic("invalid address")
	}
	owner = newOwner
}

// --- read API (used by the web client through vm/qeval) ---

func GetWidth() int    { return Width }
func GetHeight() int   { return Height }
func Price() int64     { return price }
func Owner() address   { return owner }
func Painted() int     { return board.Painted() }
func Revenue() int64   { return revenue }
func Paints() int64    { return paints }
func MaxBatchSize() int { return maxBatch }

// Pixel returns the color index at (x, y); 0 means never painted.
func Pixel(x, y int) int { return int(board.Get(x, y)) }

// Rows returns rows [from, to) as one hex digit per pixel, Width digits per
// row, with no separators. Clients page through the grid with it.
func Rows(from, to int) string { return board.Rows(from, to) }

// Version is the number of successful paint calls so far. Clients remember
// it and ask DirtyRows for what changed since.
func Version() int64 { return version }

// DirtyRows lists the rows painted after version `since`, as "y,y,y" in
// ascending order. DirtyRows(0) is every row that was ever painted, which
// is all a fresh client needs to load: the others are blank.
func DirtyRows(since int64) string {
	if since < 0 {
		since = 0
	}
	var sb strings.Builder
	for y, v := range rowVersion {
		if v <= since {
			continue
		}
		if sb.Len() > 0 {
			sb.WriteByte(',')
		}
		sb.WriteString(strconv.Itoa(y))
	}
	return sb.String()
}

// Palette returns the 16 palette colors as comma-separated CSS hex values,
// index 0 being the blank color.
func Palette() string {
	return strings.Join(canvas.Palette[:], ",")
}

// Render shows the game stats on gnoweb. The path is ignored.
func Render(_ string) string {
	var sb strings.Builder
	sb.WriteString("# Million Gno\n\n")
	sb.WriteString("A pay-per-pixel canvas. Pick a color, pay the price, own the pixel until someone repaints it. Payments go to the admin wallet, which paints for free.\n\n")
	sb.WriteString("| | |\n|---|---|\n")
	sb.WriteString(ufmt.Sprintf("| Size | %d x %d |\n", Width, Height))
	sb.WriteString(ufmt.Sprintf("| Price per pixel | %d%s |\n", price, Denom))
	sb.WriteString(ufmt.Sprintf("| Pixels painted | %d / %d |\n", board.Painted(), Width*Height))
	sb.WriteString(ufmt.Sprintf("| Paint calls | %d |\n", paints))
	sb.WriteString(ufmt.Sprintf("| Version | %d |\n", version))
	sb.WriteString(ufmt.Sprintf("| Revenue | %d%s |\n", revenue, Denom))
	sb.WriteString(ufmt.Sprintf("| Admin | %s |\n", owner.String()))
	sb.WriteString("\n## Palette\n\n")
	for i := 1; i <= int(canvas.MaxColor); i++ {
		sb.WriteString(ufmt.Sprintf("- %d: `%s`\n", i, canvas.Palette[i]))
	}
	sb.WriteString("\n## Paint\n\n")
	sb.WriteString("- [Paint one pixel](" + Realm + "$help&func=Paint): `Paint(x, y, color)` with `-send <price>ugnot`\n")
	sb.WriteString("- [Paint a batch](" + Realm + "$help&func=PaintBatch): `PaintBatch(\"x,y,color;x,y,color\")` with `-send <price*count>ugnot`\n")
	return sb.String()
}

// Realm is this realm's gnoweb path.
const Realm = "/r/g19t6f4f4ptt3m949jznalfsx2h8aj696llul0nj/million/v0"

// Package canvas is a fixed-size, 16-color pixel grid.
//
// It holds no chain state and knows nothing about payments: the realm
// gno.land/r/g1v7s3j506wqul2zwt90awgjphpx4ztwga0926f7/gnodraw/v0 wraps it with pricing and access control.
//
// Storage layout: one []byte per row, allocated on first paint. A row that
// was never painted is nil and costs nothing. Each byte holds a palette
// index; Blank (0) means "never painted".
package canvas

import (
	"errors"
	"strconv"
	"strings"
)

const (
	// Blank is the color of a pixel nobody painted. It cannot be painted.
	Blank byte = 0
	// MaxColor is the highest valid palette index.
	MaxColor byte = 15
	// MaxSide bounds width and height so x*y fits comfortably in an int.
	MaxSide = 10000
)

// Palette maps a color index to its CSS hex value. Index 0 is Blank and is
// rendered as white by clients.
var Palette = [MaxColor + 1]string{
	"#ffffff", // 0 blank
	"#ffffff", // 1 white
	"#e4e4e4", // 2 light gray
	"#888888", // 3 gray
	"#222222", // 4 black
	"#ffa7d1", // 5 pink
	"#e50000", // 6 red
	"#e59500", // 7 orange
	"#a06a42", // 8 brown
	"#e5d900", // 9 yellow
	"#94e044", // 10 lime
	"#02be01", // 11 green
	"#00d3dd", // 12 cyan
	"#0083c7", // 13 blue
	"#cf6ee4", // 14 magenta
	"#820080", // 15 purple
}

var (
	ErrOutOfRange   = errors.New("canvas: pixel out of range")
	ErrInvalidColor = errors.New("canvas: color must be between 1 and 15")
	ErrBadPixel     = errors.New("canvas: pixel must be x,y,color")
)

// Pixel is one paint request.
type Pixel struct {
	X, Y  int
	Color byte
}

// Canvas is a width x height grid of palette indexes.
type Canvas struct {
	width, height int
	rows          [][]byte
	painted       int
}

// New returns an empty canvas. It panics on a non-positive or oversized side.
func New(width, height int) *Canvas {
	if width <= 0 || height <= 0 || width > MaxSide || height > MaxSide {
		panic("canvas: width and height must be between 1 and " + strconv.Itoa(MaxSide))
	}
	return &Canvas{
		width:  width,
		height: height,
		rows:   make([][]byte, height),
	}
}

func (c *Canvas) Width() int  { return c.width }
func (c *Canvas) Height() int { return c.height }

// Painted is the number of pixels that are not Blank.
func (c *Canvas) Painted() int { return c.painted }

// Check reports whether p can be painted on this canvas.
func (c *Canvas) Check(p Pixel) error {
	if p.X < 0 || p.Y < 0 || p.X >= c.width || p.Y >= c.height {
		return ErrOutOfRange
	}
	if p.Color == Blank || p.Color > MaxColor {
		return ErrInvalidColor
	}
	return nil
}

// Get returns the color at (x, y). Out-of-range coordinates panic.
func (c *Canvas) Get(x, y int) byte {
	if x < 0 || y < 0 || x >= c.width || y >= c.height {
		panic(ErrOutOfRange)
	}
	row := c.rows[y]
	if row == nil {
		return Blank
	}
	return row[x]
}

// Set paints p. It panics when Check(p) fails.
func (c *Canvas) Set(p Pixel) {
	if err := c.Check(p); err != nil {
		panic(err)
	}
	row := c.rows[p.Y]
	if row == nil {
		row = make([]byte, c.width)
		c.rows[p.Y] = row
	}
	if row[p.X] == Blank {
		c.painted++
	}
	row[p.X] = p.Color
}

// Rows encodes rows [from, to) as one hex digit per pixel, row after row,
// with no separator. Clients slice it with the known width.
func (c *Canvas) Rows(from, to int) string {
	if from < 0 || to > c.height || from > to {
		panic(ErrOutOfRange)
	}
	var sb strings.Builder
	sb.Grow((to - from) * c.width)
	for y := from; y < to; y++ {
		row := c.rows[y]
		if row == nil {
			for x := 0; x < c.width; x++ {
				sb.WriteByte('0')
			}
			continue
		}
		for _, color := range row {
			sb.WriteByte(hexDigit(color))
		}
	}
	return sb.String()
}

// ParsePixels decodes "x,y,color;x,y,color;...". A trailing ';' is allowed.
// It validates the syntax and the color range but not the coordinates,
// which depend on the canvas: call Check for that.
func ParsePixels(s string) ([]Pixel, error) {
	s = strings.TrimSuffix(s, ";")
	if s == "" {
		return nil, ErrBadPixel
	}
	parts := strings.Split(s, ";")
	pixels := make([]Pixel, 0, len(parts))
	for _, part := range parts {
		fields := strings.Split(part, ",")
		if len(fields) != 3 {
			return nil, ErrBadPixel
		}
		x, err := strconv.Atoi(fields[0])
		if err != nil {
			return nil, ErrBadPixel
		}
		y, err := strconv.Atoi(fields[1])
		if err != nil {
			return nil, ErrBadPixel
		}
		color, err := ParseColor(fields[2])
		if err != nil {
			return nil, err
		}
		pixels = append(pixels, Pixel{X: x, Y: y, Color: color})
	}
	return pixels, nil
}

// ParseColor converts a decimal color index, rejecting Blank.
func ParseColor(s string) (byte, error) {
	n, err := strconv.Atoi(s)
	if err != nil || n <= int(Blank) || n > int(MaxColor) {
		return 0, ErrInvalidColor
	}
	return byte(n), nil
}

// Encode is the inverse of ParsePixels.
func Encode(pixels []Pixel) string {
	var sb strings.Builder
	for i, p := range pixels {
		if i > 0 {
			sb.WriteByte(';')
		}
		sb.WriteString(strconv.Itoa(p.X))
		sb.WriteByte(',')
		sb.WriteString(strconv.Itoa(p.Y))
		sb.WriteByte(',')
		sb.WriteString(strconv.Itoa(int(p.Color)))
	}
	return sb.String()
}

func hexDigit(v byte) byte {
	if v < 10 {
		return '0' + v
	}
	return 'a' + v - 10
}

package canvas

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestNewRejectsBadSizes(t *testing.T) {
	for _, tc := range []struct{ w, h int }{{0, 1}, {1, 0}, {-1, 1}, {MaxSide + 1, 1}, {1, MaxSide + 1}} {
		func() {
			defer func() {
				if r := recover(); r == nil {
					t.Errorf("New(%d, %d) did not panic", tc.w, tc.h)
				}
			}()
			New(tc.w, tc.h)
		}()
	}
}

func TestSetGet(t *testing.T) {
	c := New(4, 3)
	uassert.Equal(t, 4, c.Width())
	uassert.Equal(t, 3, c.Height())
	uassert.Equal(t, 0, c.Painted())
	uassert.Equal(t, Blank, c.Get(3, 2))

	c.Set(Pixel{X: 3, Y: 2, Color: 6})
	uassert.Equal(t, byte(6), c.Get(3, 2))
	uassert.Equal(t, 1, c.Painted())

	// Repainting the same pixel does not count twice.
	c.Set(Pixel{X: 3, Y: 2, Color: 7})
	uassert.Equal(t, byte(7), c.Get(3, 2))
	uassert.Equal(t, 1, c.Painted())

	// Other rows stay unallocated and blank.
	uassert.Equal(t, Blank, c.Get(0, 0))
	uassert.True(t, c.rows[0] == nil, "row 0 should stay nil")
}

func TestCheck(t *testing.T) {
	c := New(2, 2)
	tests := []struct {
		name string
		p    Pixel
		err  error
	}{
		{"ok", Pixel{0, 0, 1}, nil},
		{"ok max", Pixel{1, 1, MaxColor}, nil},
		{"x negative", Pixel{-1, 0, 1}, ErrOutOfRange},
		{"y negative", Pixel{0, -1, 1}, ErrOutOfRange},
		{"x too big", Pixel{2, 0, 1}, ErrOutOfRange},
		{"y too big", Pixel{0, 2, 1}, ErrOutOfRange},
		{"blank color", Pixel{0, 0, Blank}, ErrInvalidColor},
		{"color too big", Pixel{0, 0, MaxColor + 1}, ErrInvalidColor},
	}
	for _, tc := range tests {
		got := c.Check(tc.p)
		if got != tc.err {
			t.Errorf("%s: got %v, want %v", tc.name, got, tc.err)
		}
	}
}

func TestRows(t *testing.T) {
	c := New(3, 3)
	uassert.Equal(t, "000000000", c.Rows(0, 3))
	c.Set(Pixel{X: 1, Y: 1, Color: 15})
	c.Set(Pixel{X: 2, Y: 2, Color: 10})
	uassert.Equal(t, "000", c.Rows(0, 1))
	uassert.Equal(t, "0f0", c.Rows(1, 2))
	uassert.Equal(t, "0f000a", c.Rows(1, 3))
	uassert.Equal(t, "", c.Rows(2, 2))

	for _, r := range [][2]int{{-1, 1}, {0, 4}, {2, 1}} {
		func() {
			defer func() {
				if rec := recover(); rec == nil {
					t.Errorf("Rows(%d, %d) did not panic", r[0], r[1])
				}
			}()
			c.Rows(r[0], r[1])
		}()
	}
}

func TestParsePixels(t *testing.T) {
	px, err := ParsePixels("0,0,1;5,7,15;")
	uassert.NoError(t, err)
	uassert.Equal(t, 2, len(px))
	if px[0] != (Pixel{0, 0, 1}) || px[1] != (Pixel{5, 7, 15}) {
		t.Errorf("unexpected pixels: %v", px)
	}

	for _, bad := range []string{"", ";", "1,2", "1,2,3,4", "a,2,3", "1,b,3", "1,2,c", "1,2,0", "1,2,16", "1,2,-1"} {
		if _, err := ParsePixels(bad); err == nil {
			t.Errorf("ParsePixels(%q) accepted invalid input", bad)
		}
	}
}

func TestEncodeRoundTrip(t *testing.T) {
	in := []Pixel{{0, 0, 1}, {999, 999, 15}, {3, 4, 8}}
	s := Encode(in)
	uassert.Equal(t, "0,0,1;999,999,15;3,4,8", s)
	out, err := ParsePixels(s)
	uassert.NoError(t, err)
	uassert.Equal(t, len(in), len(out))
	for i := range in {
		if in[i] != out[i] {
			t.Errorf("pixel %d: got %v, want %v", i, out[i], in[i])
		}
	}
}

// Package gnodraw is a pay-per-pixel collaborative canvas: anyone can paint
// any pixel of a Width x Height grid in one of 15 colors by sending exactly
// Price() ugnot per pixel along with the call. Pixels can be repainted by
// anyone, for the same price. Payments are forwarded to the admin wallet
// as they arrive, and the admin paints for free.
//
// The grid logic lives in gno.land/p/g1v7s3j506wqul2zwt90awgjphpx4ztwga0926f7/canvas/v0; this realm adds the
// payment guard, the owner controls and the read API used by the web client.
package gnodraw

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/g1v7s3j506wqul2zwt90awgjphpx4ztwga0926f7/canvas/v0"
	"gno.land/p/nt/ufmt/v0"
)

const (
	// Width and Height are fixed for the life of this version: changing
	// them would change the storage layout, so it means a new /vN.
	// 1250 x 800 is one million pixels in a 16:10 laptop aspect ratio.
	Width  = 1250
	Height = 800

	// DefaultMaxBatch bounds a single PaintBatch call so one tx cannot blow
	// the block gas limit or overflow the price arithmetic. The owner can
	// change it at runtime with SetMaxBatch, up to HardMaxBatch.
	DefaultMaxBatch = 5000
	HardMaxBatch    = 20000

	// DefaultPrice is the initial price per pixel, in ugnot (0.05 GNOT).
	DefaultPrice int64 = 50_000

	// DefaultAdmin receives every payment, paints for free and holds the
	// owner controls. Change it before deploying; TransferOwnership moves
	// it afterwards.
	DefaultAdmin = "g1v7s3j506wqul2zwt90awgjphpx4ztwga0926f7"

	Denom = "ugnot"
)

var (
	board    = canvas.New(Width, Height)
	price    = DefaultPrice
	maxBatch = DefaultMaxBatch
	owner    = address(DefaultAdmin)

	// Stats.
	revenue int64 // total ugnot ever paid for pixels
	paints  int64 // number of successful Paint/PaintBatch calls

	// Change tracking, so clients fetch only the rows that moved.
	// version bumps once per successful paint call; rowVersion holds the
	// version of the last paint that touched each row (0 = never painted).
	version    int64
	rowVersion = make([]int64, Height)
)

// Paint colors one pixel. Send exactly Price() ugnot (nothing for the admin).
func Paint(cur realm, x, y, color int) {
	if color <= 0 || color > int(canvas.MaxColor) {
		panic(canvas.ErrInvalidColor)
	}
	paint([]canvas.Pixel{{X: x, Y: y, Color: byte(color)}}, cur)
}

// PaintBatch colors up to MaxBatchSize() pixels in one call. The argument is
// "x,y,color;x,y,color;...". Send exactly Price() * count ugnot (nothing
// for the admin).
func PaintBatch(cur realm, pixels string) {
	px, err := canvas.ParsePixels(pixels)
	if err != nil {
		panic(err)
	}
	paint(px, cur)
}

// paint takes the realm as its LAST parameter on purpose: a realm first
// parameter would make it a crossing function and Previous() would then
// be this realm instead of the user.
func paint(px []canvas.Pixel, rlm realm) {
	if !rlm.IsCurrent() {
		panic("spoofed realm")
	}
	// Payment guard: unsafe.OriginSend() describes the coins attached to
	// the transaction, which only provably landed here when the caller is
	// a plain user call (no intermediate or ephemeral realm). Keep the two
	// checks together. unsafe is imported for OriginSend only; caller
	// identity always comes from the realm handle.
	if !rlm.Previous().IsUserCall() {
		panic("must be called directly by a user (maketx call)")
	}
	painter := rlm.Previous().Address()
	n := len(px)
	if n == 0 {
		panic("nothing to paint")
	}
	if n > maxBatch {
		panic(ufmt.Sprintf("too many pixels: %d > %d", n, maxBatch))
	}
	for _, p := range px {
		if err := board.Check(p); err != nil {
			panic(err)
		}
	}

	cost := price * int64(n)
	if painter == owner {
		cost = 0 // the admin paints for free
	}
	if sent := sentUgnot(unsafe.OriginSend()); sent != cost {
		panic(ufmt.Sprintf("must send exactly %d%s for %d pixel(s), got %d%s", cost, Denom, n, sent, Denom))
	}
	if cost > 0 {
		// Forward the payment to the admin right away, so nothing
		// accumulates in the realm. BankerTypeOriginSend can only move
		// what this very message sent, which is exactly cost.
		bnk := banker.NewBanker(banker.BankerTypeOriginSend, rlm)
		bnk.SendCoins(rlm.Address(), owner, chain.NewCoins(chain.NewCoin(Denom, cost)))
	}

	version++
	for _, p := range px {
		board.Set(p)
		rowVersion[p.Y] = version
	}
	revenue += cost
	paints++

	// The pixel list itself is not emitted: event attribute values are
	// size-capped by the node and a full batch exceeds it. Clients re-read
	// Rows() after a paint.
	chain.Emit("Paint",
		"painter", painter.String(),
		"count", strconv.Itoa(n),
		"paid", strconv.Itoa(int(cost))+Denom,
	)
}

// sentUgnot returns the ugnot amount in coins and rejects any other denom,
// so a caller cannot pay with something the realm does not price.
func sentUgnot(coins chain.Coins) int64 {
	var amount int64
	for _, c := range coins {
		if c.Denom != Denom {
			panic("only " + Denom + " is accepted")
		}
		amount += c.Amount
	}
	return amount
}

// --- owner controls ---

// assertOwner panics unless the verified caller behind rlm is the owner.
// The realm is deliberately not the first parameter (see paint); the
// leading blank int is the same idiom gno.land/p/nt/ownable uses.
func assertOwner(_ int, rlm realm) {
	if !rlm.IsCurrent() {
		panic("spoofed realm")
	}
	if rlm.Previous().Address() != owner {
		panic("owner only")
	}
}

// SetPrice changes the price per pixel, in ugnot. Zero makes painting free
// for everyone.
func SetPrice(cur realm, ugnot int64) {
	assertOwner(0, cur)
	if ugnot < 0 {
		panic("price must not be negative")
	}
	price = ugnot
}

// SetMaxBatch changes the maximum pixels per PaintBatch call, 1..HardMaxBatch.
func SetMaxBatch(cur realm, n int) {
	assertOwner(0, cur)
	if n < 1 || n > HardMaxBatch {
		panic(ufmt.Sprintf("max batch must be between 1 and %d", HardMaxBatch))
	}
	maxBatch = n
}

// Withdraw sends amount ugnot held by the realm to the given address.
// Payments are forwarded on arrival, so this only matters for coins sent
// to the realm outside of a paint call.
func Withdraw(cur realm, to address, amount int64) {
	assertOwner(0, cur)
	if !to.IsValid() {
		panic("invalid address")
	}
	if amount <= 0 {
		panic("amount must be positive")
	}
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin(Denom, amount)))
}

// TransferOwnership hands the admin role (payments, free painting and the
// owner controls) to newOwner.
func TransferOwnership(cur realm, newOwner address) {
	assertOwner(0, cur)
	if !newOwner.IsValid() {
		panic("invalid address")
	}
	owner = newOwner
}

// --- read API (used by the web client through vm/qeval) ---

func GetWidth() int    { return Width }
func GetHeight() int   { return Height }
func Price() int64     { return price }
func Owner() address   { return owner }
func Painted() int     { return board.Painted() }
func Revenue() int64   { return revenue }
func Paints() int64    { return paints }
func MaxBatchSize() int { return maxBatch }

// Pixel returns the color index at (x, y); 0 means never painted.
func Pixel(x, y int) int { return int(board.Get(x, y)) }

// Rows returns rows [from, to) as one hex digit per pixel, Width digits per
// row, with no separators. Clients page through the grid with it.
func Rows(from, to int) string { return board.Rows(from, to) }

// Version is the number of successful paint calls so far. Clients remember
// it and ask DirtyRows for what changed since.
func Version() int64 { return version }

// DirtyRows lists the rows painted after version `since`, as "y,y,y" in
// ascending order. DirtyRows(0) is every row that was ever painted, which
// is all a fresh client needs to load: the others are blank.
func DirtyRows(since int64) string {
	if since < 0 {
		since = 0
	}
	var sb strings.Builder
	for y, v := range rowVersion {
		if v <= since {
			continue
		}
		if sb.Len() > 0 {
			sb.WriteByte(',')
		}
		sb.WriteString(strconv.Itoa(y))
	}
	return sb.String()
}

// Palette returns the 16 palette colors as comma-separated CSS hex values,
// index 0 being the blank color.
func Palette() string {
	return strings.Join(canvas.Palette[:], ",")
}

// Render shows the game stats on gnoweb. The path is ignored.
func Render(_ string) string {
	var sb strings.Builder
	sb.WriteString("# Million Gno\n\n")
	sb.WriteString("A pay-per-pixel canvas. Pick a color, pay the price, own the pixel until someone repaints it. Payments go to the admin wallet, which paints for free.\n\n")
	sb.WriteString("| | |\n|---|---|\n")
	sb.WriteString(ufmt.Sprintf("| Size | %d x %d |\n", Width, Height))
	sb.WriteString(ufmt.Sprintf("| Price per pixel | %d%s |\n", price, Denom))
	sb.WriteString(ufmt.Sprintf("| Pixels painted | %d / %d |\n", board.Painted(), Width*Height))
	sb.WriteString(ufmt.Sprintf("| Paint calls | %d |\n", paints))
	sb.WriteString(ufmt.Sprintf("| Version | %d |\n", version))
	sb.WriteString(ufmt.Sprintf("| Revenue | %d%s |\n", revenue, Denom))
	sb.WriteString(ufmt.Sprintf("| Admin | %s |\n", owner.String()))
	sb.WriteString("\n## Palette\n\n")
	for i := 1; i <= int(canvas.MaxColor); i++ {
		sb.WriteString(ufmt.Sprintf("- %d: `%s`\n", i, canvas.Palette[i]))
	}
	sb.WriteString("\n## Paint\n\n")
	sb.WriteString("- [Paint one pixel](" + Realm + "$help&func=Paint): `Paint(x, y, color)` with `-send <price>ugnot`\n")
	sb.WriteString("- [Paint a batch](" + Realm + "$help&func=PaintBatch): `PaintBatch(\"x,y,color;x,y,color\")` with `-send <price*count>ugnot`\n")
	return sb.String()
}

// Realm is this realm's gnoweb path.
const Realm = "/r/g1v7s3j506wqul2zwt90awgjphpx4ztwga0926f7/gnodraw/v0"

// Package faucet hands a small amount of GNOT to someone who has none, on the
// record, in two calls that are meant to travel in one transaction.
//
// The chain's own faucet is gated and the people who most need a first coin
// are exactly the people who cannot ask for one: an empty account cannot pay
// the gas to call anything. So somebody else files the request on their
// behalf, an approver releases it, and both halves are on chain with a reason
// attached.
//
// # Why two calls and not one bank send
//
// [Request] is permissionless and [Approve] is not. Splitting them puts the
// ask, its reason and who made it on chain even when the answer is no, and
// makes every payout name the request it settles. A plain send would leave a
// transfer with no why, and no way to refuse one in public.
//
// They are meant to be sent together. A tm2 transaction carries a LIST of
// messages, runs them in order and stops at the first failure, and a failed
// transaction writes none of their state: only the fee and the sequence
// survive (tm2/pkg/sdk/baseapp.go, runMsgs and WriteCheckpoint). So a request
// and its approval in one transaction either both happen or neither does.
//
// # The id the second message cannot know yet
//
// [Approve] names a request by id, and message 2 of a transaction cannot read
// what message 1 returned. A caller therefore reads [NextID] first and writes
// that number into the approval, which is a race: another Request landing in
// between shifts the id under it, and the approval would pay a stranger.
//
// That is why [Approve] also takes the recipient and the amount it believes it
// is approving, and refuses when the stored request disagrees. The race then
// costs a failed transaction instead of the wrong person's rent.
//
// # What bounds the damage
//
// The faucet spends only what has been sent to its own address, never the
// approver's balance, so the float is the ceiling and topping it up is a
// deliberate act. [MaxPerRequest] caps any single payout under that, and
// [Withdraw] takes the float back.
package faucet

import (
	"strconv"
	"strings"

	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
)

const (
	// Denom is the only coin this faucet holds or pays.
	Denom = "ugnot"
	// Path is this realm's package path; its float is held at the address
	// derived from it.
	Path = "gno.land/r/moul/faucet/v0"
	// Link is Path as a gnoweb route.
	Link = "/r/moul/faucet/v0"
)

// Owner funds the faucet, approves by default, and is the only account that
// can change who else approves or take the float back.
//
// Hardcoded rather than captured from the deployer: inside a plain
// `func Test(t *testing.T)` the gno test runner reports OriginCaller() as the
// EMPTY address, so an owner seeded from it is empty in every test and
// something else on chain. That divergence is where an authorization bug
// hides, so the address is written down.
const Owner = address("g1manfred47kzduec920z88wfr64ylksmdcedlf5")

// The three states a request can be in. A request is decided exactly once.
const (
	StatusPending = "pending"
	StatusSent    = "sent"
	StatusDenied  = "denied"
)

const (
	// DefaultMaxPerRequest is the starting cap on a single payout, 200 GNOT.
	// It is a guard against a fat finger, not against a hostile approver:
	// an approver can raise nothing, but the Owner can.
	DefaultMaxPerRequest = 200_000_000

	// MaxReasonLen bounds the stored reason. It is rendered on a page, so it
	// is both a storage cost and a display one.
	MaxReasonLen = 280

	// idWidth pads the avl key. gno's ufmt supports no width flags, so the
	// padding is done by hand; unpadded numeric keys sort "1","10","2" and
	// the request list would lose its order past nine entries.
	idWidth = 12
)

// request is one ask. It is unexported because avl stores `any` and the
// readable surface of this realm is its views and its page, not a struct
// another realm would have to depend on.
type request struct {
	ID      int64
	To      address
	Amount  int64 // ugnot
	Reason  string
	By      address // who filed it, which is usually not who receives it
	Asked   int64   // chain height at filing
	Status  string
	Judge   address // who decided, zero while pending
	Decided int64   // chain height of the decision
	Note    string  // the denial reason; empty otherwise
}

var (
	requests  avl.Tree // padded id -> *request
	paid      avl.Tree // recipient address -> int64 ugnot received in total
	approvers avl.Tree // approver address -> bool

	nextID        int64
	maxPerRequest int64

	totalSent   int64
	sentCount   int64
	deniedCount int64
	pendingN    int64
)

func init() { reset() }

// reset installs an empty faucet. Also called by the tests: realm globals
// persist for a whole test binary and examples run after every Test, so a
// pinned Render has to start from a known state.
func reset() {
	requests = avl.Tree{}
	paid = avl.Tree{}
	approvers = avl.Tree{}
	approvers.Set(Owner.String(), true)
	nextID = 1
	maxPerRequest = DefaultMaxPerRequest
	totalSent, sentCount, deniedCount, pendingN = 0, 0, 0, 0
}

// Address is where the float sits: this realm's own package address. Fund the
// faucet by sending ugnot to it, with a plain bank send or with [Fund].
func Address() address { return chain.PackageAddress(Path) }

// Balance is what the faucet can actually pay out right now.
func Balance() int64 {
	return banker.NewReadonlyBanker().GetCoins(Address()).AmountOf(Denom)
}

// NextID is the id the next [Request] will be given.
//
// Read it to build the [Approve] half of a two-message transaction, and pass
// the recipient and amount to Approve so that a request landing in between
// fails the transaction instead of being paid by it.
func NextID() int64 { return nextID }

// MaxPerRequest is the current cap on a single payout, in ugnot.
func MaxPerRequest() int64 { return maxPerRequest }

// TotalSent, SentCount, DeniedCount and Pending are the running tallies.
func TotalSent() int64   { return totalSent }
func SentCount() int64   { return sentCount }
func DeniedCount() int64 { return deniedCount }
func Pending() int64     { return pendingN }

// Requests is how many requests have ever been filed.
func Requests() int { return requests.Size() }

// IsApprover reports whether addr may approve or deny.
func IsApprover(addr string) bool { return approvers.Has(addr) }

// ReceivedBy is everything this faucet has ever paid to addr.
func ReceivedBy(addr string) int64 {
	if v := paid.Get(addr); v != nil {
		return v.(int64)
	}
	return 0
}

// Status is the state of request id: "pending", "sent", "denied", or "" when
// no such request exists.
func Status(id int64) string {
	r := find(id)
	if r == nil {
		return ""
	}
	return r.Status
}

// Fund credits the ugnot sent with the call to the float. Coins sent straight
// to [Address] land there too; they just do not emit an event.
func Fund(cur realm) {
	from := unsafe.PreviousRealm().Address()
	amount := unsafe.OriginSend().AmountOf(Denom)
	if amount <= 0 {
		panic("faucet: send some " + Denom + " with the call")
	}
	chain.Emit("Fund", "from", from.String(), "amount", strconv.FormatInt(amount, 10))
}

// Request files an ask for amount ugnot to be paid to `to`, and returns its
// id. Anyone may file, for anyone, which is the point: the account that needs
// the coins is the one that cannot pay to ask for them.
//
// Filing costs the filer gas and nothing else, and moves no money.
func Request(cur realm, to string, amount int64, reason string) int64 {
	by := unsafe.PreviousRealm().Address()
	dst := address(to)
	if !dst.IsValid() {
		panic("faucet: " + to + " is not a valid address")
	}
	if amount <= 0 {
		panic("faucet: amount must be a positive number of " + Denom)
	}
	if amount > maxPerRequest {
		panic("faucet: " + strconv.FormatInt(amount, 10) + Denom +
			" is over the per-request cap of " + strconv.FormatInt(maxPerRequest, 10) + Denom)
	}
	reason = strings.TrimSpace(reason)
	if reason == "" {
		panic("faucet: say what it is for")
	}
	if len(reason) > MaxReasonLen {
		panic("faucet: reason is longer than " + strconv.Itoa(MaxReasonLen) + " bytes")
	}

	id := nextID
	nextID++
	requests.Set(key(id), &request{
		ID:     id,
		To:     dst,
		Amount: amount,
		Reason: reason,
		By:     by,
		Asked:  runtime.ChainHeight(),
		Status: StatusPending,
	})
	pendingN++

	chain.Emit("Request",
		"id", strconv.FormatInt(id, 10),
		"to", dst.String(),
		"amount", strconv.FormatInt(amount, 10),
		"by", by.String(),
	)
	return id
}

// Approve pays request id out of the float. Approvers only.
//
// wantTo and wantAmount are not redundant: they are what makes it safe to put
// Approve in the same transaction as the Request it settles. The id has to be
// guessed from [NextID] before either message is signed, and this call refuses
// when the request sitting at that id is not the one the caller described.
func Approve(cur realm, id int64, wantTo string, wantAmount int64) {
	judge := unsafe.PreviousRealm().Address()
	mustApprove(judge)

	r := find(id)
	if r == nil {
		panic("faucet: no request " + strconv.FormatInt(id, 10))
	}
	if r.Status != StatusPending {
		panic("faucet: request " + strconv.FormatInt(id, 10) + " is already " + r.Status)
	}
	if r.To.String() != wantTo || r.Amount != wantAmount {
		panic("faucet: request " + strconv.FormatInt(id, 10) + " pays " +
			strconv.FormatInt(r.Amount, 10) + Denom + " to " + r.To.String() +
			", not " + strconv.FormatInt(wantAmount, 10) + Denom + " to " + wantTo +
			"; the id moved under you, nothing was paid")
	}
	if bal := Balance(); bal < r.Amount {
		panic("faucet: float is " + strconv.FormatInt(bal, 10) + Denom +
			", request needs " + strconv.FormatInt(r.Amount, 10) + Denom)
	}

	banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(
		cur.Address(), r.To, chain.NewCoins(chain.NewCoin(Denom, r.Amount)))

	r.Status = StatusSent
	r.Judge = judge
	r.Decided = runtime.ChainHeight()
	paid.Set(r.To.String(), ReceivedBy(r.To.String())+r.Amount)
	totalSent += r.Amount
	sentCount++
	pendingN--

	chain.Emit("Approve",
		"id", strconv.FormatInt(id, 10),
		"to", r.To.String(),
		"amount", strconv.FormatInt(r.Amount, 10),
		"by", judge.String(),
	)
}

// Deny closes a request unpaid, with a reason that goes on the page. The
// reason is the whole value of denying in public rather than ignoring it.
func Deny(cur realm, id int64, why string) {
	judge := unsafe.PreviousRealm().Address()
	mustApprove(judge)

	r := find(id)
	if r == nil {
		panic("faucet: no request " + strconv.FormatInt(id, 10))
	}
	if r.Status != StatusPending {
		panic("faucet: request " + strconv.FormatInt(id, 10) + " is already " + r.Status)
	}
	why = strings.TrimSpace(why)
	if why == "" {
		panic("faucet: say why")
	}
	if len(why) > MaxReasonLen {
		panic("faucet: reason is longer than " + strconv.Itoa(MaxReasonLen) + " bytes")
	}

	r.Status = StatusDenied
	r.Judge = judge
	r.Decided = runtime.ChainHeight()
	r.Note = why
	deniedCount++
	pendingN--

	chain.Emit("Deny", "id", strconv.FormatInt(id, 10), "by", judge.String())
}

// AddApprover lets addr approve and deny. Owner only.
func AddApprover(cur realm, addr string) {
	mustOwn(unsafe.PreviousRealm().Address())
	a := address(addr)
	if !a.IsValid() {
		panic("faucet: " + addr + " is not a valid address")
	}
	approvers.Set(a.String(), true)
	chain.Emit("AddApprover", "addr", a.String())
}

// RemoveApprover revokes addr. Owner only, and the Owner cannot be removed:
// a faucet with no approver is a faucet with a locked float.
func RemoveApprover(cur realm, addr string) {
	mustOwn(unsafe.PreviousRealm().Address())
	if addr == Owner.String() {
		panic("faucet: the owner is always an approver")
	}
	// avl's Remove returns (value, removed), unlike Get which returns one
	// value; the comma-ok is required here and forbidden there.
	if _, removed := approvers.Remove(addr); !removed {
		panic("faucet: " + addr + " is not an approver")
	}
	chain.Emit("RemoveApprover", "addr", addr)
}

// SetMaxPerRequest changes the per-request cap, in ugnot. Owner only.
func SetMaxPerRequest(cur realm, amount int64) {
	mustOwn(unsafe.PreviousRealm().Address())
	if amount <= 0 {
		panic("faucet: cap must be positive")
	}
	maxPerRequest = amount
	chain.Emit("SetMaxPerRequest", "amount", strconv.FormatInt(amount, 10))
}

// Withdraw returns amount ugnot of the float to the Owner. Owner only.
//
// This is what makes funding the faucet reversible, and it is deliberately
// not payable to an arbitrary address: an approver who wanted to move money
// somewhere has to file a request for it like everyone else.
func Withdraw(cur realm, amount int64) {
	mustOwn(unsafe.PreviousRealm().Address())
	if amount <= 0 {
		panic("faucet: amount must be positive")
	}
	if bal := Balance(); amount > bal {
		panic("faucet: float is " + strconv.FormatInt(bal, 10) + Denom)
	}
	banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(
		cur.Address(), Owner, chain.NewCoins(chain.NewCoin(Denom, amount)))
	chain.Emit("Withdraw", "amount", strconv.FormatInt(amount, 10))
}

func mustOwn(caller address) {
	if caller != Owner {
		panic("faucet: owner only")
	}
}

func mustApprove(caller address) {
	if !approvers.Has(caller.String()) {
		panic("faucet: " + caller.String() + " is not an approver")
	}
}

func find(id int64) *request {
	v := requests.Get(key(id))
	if v == nil {
		return nil
	}
	return v.(*request)
}

// key pads an id to idWidth digits so the avl tree iterates in filing order.
func key(id int64) string {
	s := strconv.FormatInt(id, 10)
	for len(s) < idWidth {
		s = "0" + s
	}
	return s
}

package faucet

import (
	"chain"
	"chain/banker"
	"testing"

	"gno.land/p/nt/uassert/v0"
	"gno.land/p/nt/urequire/v0"
)

const (
	zoe  = address("g12cs4cehujpffpjpywmkqj43m6u5ya53nj69sjz") // a friend with nothing
	kim  = address("g1jvh5ukk07dvd57fxefcp5aa29xaydxmxs7myyp") // a second approver
	carl = address("g1us8428u2a5satrlxzagqqa5m6vmuze025anjlj") // nobody in particular
)

func balanceOf(a address) int64 {
	return banker.NewReadonlyBanker().GetCoins(a).AmountOf(Denom)
}

// fund puts ugnot in the float the way a bank send to the realm address does,
// with no call involved. Approve spends this, so a test that funds more than
// it pays leaves a balance behind and ExampleRender sees it.
func fund(n int64) {
	testing.IssueCoins(Address(), chain.NewCoins(chain.NewCoin(Denom, n)))
}

func TestFreshFaucetIsEmptyAndOwned(t *testing.T) {
	reset()
	uassert.True(t, Owner.IsValid(), "the owner is a real address")
	uassert.True(t, Address().IsValid(), "the float address")
	uassert.True(t, zoe.IsValid())
	uassert.True(t, kim.IsValid())
	uassert.True(t, carl.IsValid())

	uassert.Equal(t, 0, Requests(), "nothing is seeded")
	uassert.Equal(t, int64(1), NextID())
	uassert.Equal(t, int64(0), TotalSent())
	uassert.Equal(t, int64(DefaultMaxPerRequest), MaxPerRequest())
	uassert.True(t, IsApprover(Owner.String()), "the owner approves by default")
	uassert.False(t, IsApprover(carl.String()))
	uassert.Equal(t, "", Status(1), "no such request")
}

// The whole point, end to end: carl asks on zoe's behalf, the owner releases
// it, and zoe (who could never have paid the gas to ask) has coins.
func TestRequestForAFriendThenApprove(cur realm, t *testing.T) {
	reset()
	urequire.Equal(t, int64(0), Balance(), "start from an empty float")
	fund(300_000_000)

	testing.SetRealm(testing.NewUserRealm(carl))
	id := Request(cross(cur), zoe.String(), 100_000_000, "no gas, needs to try the chain")
	uassert.Equal(t, int64(1), id)
	uassert.Equal(t, StatusPending, Status(id))
	uassert.Equal(t, int64(1), Pending())
	uassert.Equal(t, int64(0), balanceOf(zoe), "a request moves nothing")
	uassert.Equal(t, int64(2), NextID(), "and the next id is now readable")

	// The filer is not an approver just because they filed.
	testing.SetRealm(testing.NewUserRealm(carl))
	uassert.AbortsContains(t, cur, "is not an approver", func() {
		Approve(cross(cur), id, zoe.String(), 100_000_000)
	})

	testing.SetRealm(testing.NewUserRealm(Owner))
	Approve(cross(cur), id, zoe.String(), 100_000_000)

	uassert.Equal(t, int64(100_000_000), balanceOf(zoe), "the coins landed")
	uassert.Equal(t, int64(200_000_000), Balance(), "out of the float, not the approver")
	uassert.Equal(t, StatusSent, Status(id))
	uassert.Equal(t, int64(100_000_000), TotalSent())
	uassert.Equal(t, int64(1), SentCount())
	uassert.Equal(t, int64(0), Pending())
	uassert.Equal(t, int64(100_000_000), ReceivedBy(zoe.String()))

	// A decision happens once.
	testing.SetRealm(testing.NewUserRealm(Owner))
	uassert.AbortsContains(t, cur, "already sent", func() {
		Approve(cross(cur), id, zoe.String(), 100_000_000)
	})

	// Put the float back so ExampleRender starts from zero.
	testing.SetRealm(testing.NewUserRealm(Owner))
	Withdraw(cross(cur), Balance())
	uassert.Equal(t, int64(0), Balance())
}

// The guard that makes it safe to sign Request and Approve in the same
// transaction before either has run. The approval names an id it had to guess
// from NextID; if a different request took that id, the amounts and the
// recipient no longer agree and nothing is paid.
func TestApproveRefusesWhenTheIDMovedUnderYou(cur realm, t *testing.T) {
	reset()
	fund(500_000_000)

	// What the caller read: the next id will be 1.
	urequire.Equal(t, int64(1), NextID())

	// What actually landed at id 1: somebody else's ask, first.
	testing.SetRealm(testing.NewUserRealm(kim))
	Request(cross(cur), kim.String(), 50_000_000, "me first")
	testing.SetRealm(testing.NewUserRealm(carl))
	Request(cross(cur), zoe.String(), 100_000_000, "for zoe")

	testing.SetRealm(testing.NewUserRealm(Owner))
	uassert.AbortsContains(t, cur, "the id moved under you, nothing was paid", func() {
		Approve(cross(cur), 1, zoe.String(), 100_000_000)
	})
	uassert.Equal(t, int64(0), balanceOf(zoe), "nobody was paid")
	uassert.Equal(t, StatusPending, Status(1), "and nothing was decided")

	// The same guard catches a wrong amount at the right id.
	testing.SetRealm(testing.NewUserRealm(Owner))
	uassert.AbortsContains(t, cur, "the id moved under you, nothing was paid", func() {
		Approve(cross(cur), 2, zoe.String(), 999_000_000)
	})

	testing.SetRealm(testing.NewUserRealm(Owner))
	Approve(cross(cur), 2, zoe.String(), 100_000_000)
	uassert.Equal(t, int64(100_000_000), balanceOf(zoe))

	testing.SetRealm(testing.NewUserRealm(Owner))
	Deny(cross(cur), 1, "already funded elsewhere")
	uassert.Equal(t, StatusDenied, Status(1))
	uassert.Equal(t, int64(1), DeniedCount())
	uassert.Equal(t, int64(0), Pending())

	testing.SetRealm(testing.NewUserRealm(Owner))
	Withdraw(cross(cur), Balance())
}

func TestRequestRefusesBadInput(cur realm, t *testing.T) {
	reset()
	tests := []struct {
		name   string
		to     string
		amount int64
		reason string
		want   string
	}{
		{"not an address", "nope", 1_000_000, "hi", "is not a valid address"},
		{"zero", zoe.String(), 0, "hi", "must be a positive number"},
		{"negative", zoe.String(), -1, "hi", "must be a positive number"},
		{"over the cap", zoe.String(), DefaultMaxPerRequest + 1, "hi", "is over the per-request cap"},
		{"no reason", zoe.String(), 1_000_000, "   ", "say what it is for"},
	}
	for _, tt := range tests {
		testing.SetRealm(testing.NewUserRealm(carl))
		uassert.AbortsContains(t, cur, tt.want, func() {
			Request(cross(cur), tt.to, tt.amount, tt.reason)
		}, tt.name)
	}
	uassert.Equal(t, 0, Requests(), "none of them were filed")
	uassert.Equal(t, int64(1), NextID(), "and the id did not move")
}

func TestApproveRefusesWhatTheFloatCannotCover(cur realm, t *testing.T) {
	reset()
	fund(10_000_000)

	testing.SetRealm(testing.NewUserRealm(carl))
	id := Request(cross(cur), zoe.String(), 100_000_000, "more than is there")

	testing.SetRealm(testing.NewUserRealm(Owner))
	uassert.AbortsContains(t, cur, "float is 10000000ugnot", func() {
		Approve(cross(cur), id, zoe.String(), 100_000_000)
	})
	uassert.Equal(t, StatusPending, Status(id), "still open, the money simply is not there")

	testing.SetRealm(testing.NewUserRealm(Owner))
	Withdraw(cross(cur), Balance())
}

func TestOnlyTheOwnerChangesWhoApproves(cur realm, t *testing.T) {
	reset()

	testing.SetRealm(testing.NewUserRealm(carl))
	uassert.AbortsContains(t, cur, "owner only", func() {
		AddApprover(cross(cur), carl.String())
	})

	testing.SetRealm(testing.NewUserRealm(Owner))
	AddApprover(cross(cur), kim.String())
	uassert.True(t, IsApprover(kim.String()))

	// A second approver can decide, but cannot widen the roster.
	fund(200_000_000)
	testing.SetRealm(testing.NewUserRealm(carl))
	id := Request(cross(cur), zoe.String(), 50_000_000, "kim vouches")
	testing.SetRealm(testing.NewUserRealm(kim))
	Approve(cross(cur), id, zoe.String(), 50_000_000)
	uassert.Equal(t, StatusSent, Status(id))

	testing.SetRealm(testing.NewUserRealm(kim))
	uassert.AbortsContains(t, cur, "owner only", func() {
		AddApprover(cross(cur), carl.String())
	})

	// The owner is the one approver that cannot be removed: a faucet with no
	// approver is a faucet with a locked float.
	testing.SetRealm(testing.NewUserRealm(Owner))
	uassert.AbortsContains(t, cur, "the owner is always an approver", func() {
		RemoveApprover(cross(cur), Owner.String())
	})
	testing.SetRealm(testing.NewUserRealm(Owner))
	RemoveApprover(cross(cur), kim.String())
	uassert.False(t, IsApprover(kim.String()))

	testing.SetRealm(testing.NewUserRealm(Owner))
	Withdraw(cross(cur), Balance())
}

func TestFundAndWithdrawAreOwnerReversible(cur realm, t *testing.T) {
	reset()
	fund(400_000_000)
	testing.SetOriginSend(chain.NewCoins(chain.NewCoin(Denom, 400_000_000)))
	testing.SetRealm(testing.NewUserRealm(kim))
	Fund(cross(cur))
	uassert.Equal(t, int64(400_000_000), Balance())

	testing.SetRealm(testing.NewUserRealm(kim))
	uassert.AbortsContains(t, cur, "owner only", func() {
		Withdraw(cross(cur), 1)
	})

	testing.SetRealm(testing.NewUserRealm(Owner))
	uassert.AbortsContains(t, cur, "float is 400000000ugnot", func() {
		Withdraw(cross(cur), 400_000_001)
	})

	before := balanceOf(Owner)
	testing.SetRealm(testing.NewUserRealm(Owner))
	Withdraw(cross(cur), 400_000_000)
	uassert.Equal(t, int64(0), Balance())
	uassert.Equal(t, before+400_000_000, balanceOf(Owner))
}

func TestSetMaxPerRequest(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(carl))
	uassert.AbortsContains(t, cur, "owner only", func() {
		SetMaxPerRequest(cross(cur), 1)
	})

	testing.SetRealm(testing.NewUserRealm(Owner))
	SetMaxPerRequest(cross(cur), 1_000_000_000)
	uassert.Equal(t, int64(1_000_000_000), MaxPerRequest())

	testing.SetRealm(testing.NewUserRealm(carl))
	id := Request(cross(cur), zoe.String(), 900_000_000, "over the old cap, under the new one")
	uassert.Equal(t, StatusPending, Status(id))
}

// A reason is arbitrary text from an arbitrary account, and this realm's path
// is permanent, so the escaping has to be right before it ships. Assert the
// dangerous SEQUENCES are dead on the page, not that some particular escape
// was chosen.
func TestRenderEscapesTheReason(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(carl))
	id := Request(cross(cur), zoe.String(), 1_000_000,
		"[click](https://evil.example) ![b](https://evil.example/p.png) <gno-columns>")

	for _, page := range []string{Render(""), Render("req/" + "1")} {
		uassert.False(t, contains(page, "](https://evil.example"), "no live link")
		uassert.False(t, contains(page, "![b]"), "no image beacon")
		uassert.False(t, contains(page, "<gno-columns>"), "no gnoweb chrome")
		uassert.True(t, contains(page, "click"), "the readable text survives")
	}
	uassert.Equal(t, StatusPending, Status(id))
}

func contains(haystack, needle string) bool {
	for i := 0; i+len(needle) <= len(haystack); i++ {
		if haystack[i:i+len(needle)] == needle {
			return true
		}
	}
	return false
}

func TestGnotFormatting(t *testing.T) {
	tests := []struct {
		in   int64
		want string
	}{
		{0, "0"},
		{1, "0.000001"},
		{1_500_000, "1.5"},
		{100_000_000, "100"},
		{5_000_000_000, "5000"},
		{-2_500_000, "-2.5"},
	}
	for _, tt := range tests {
		uassert.Equal(t, tt.want, gnot(tt.in))
	}
}

func TestReqPath(t *testing.T) {
	tests := []struct {
		in   string
		id   int64
		want bool
	}{
		{"", 0, false},
		{"req/1", 1, true},
		{"req/42", 42, true},
		{"req/0", 0, false},
		{"req/x", 0, false},
		{"req/", 0, false},
		{"other", 0, false},
	}
	for _, tt := range tests {
		id, ok := reqPath(tt.in)
		uassert.Equal(t, tt.want, ok, tt.in)
		uassert.Equal(t, tt.id, id, tt.in)
	}
}

package faucet

import (
	"strconv"
	"strings"

	"gno.land/p/nt/markdown/sanitize/v0"
)

// Render shows the float, the open asks and everything already decided.
//
// Two paths: "" is the whole board, "req/<id>" is one request.
//
// Every string on this page that a caller typed goes through sanitize before
// it is concatenated. A reason is arbitrary text from an arbitrary account and
// Render output is markdown that gnoweb parses, so an unescaped one can plant
// a link, an image beacon or gnoweb chrome on a page the realm is signing for.
// This realm's path is permanent, so that bug could only ever be fixed at a
// new path.
func Render(path string) string {
	path = strings.TrimPrefix(path, "/")
	if id, ok := reqPath(path); ok {
		return renderOne(id)
	}
	return renderBoard()
}

func renderBoard() string {
	var b strings.Builder

	b.WriteString("# GNOT faucet\n\n")
	b.WriteString(intro)
	b.WriteString("\n\n")

	b.WriteString("| | |\n| --- | ---: |\n")
	b.WriteString("| Float available | **" + gnot(Balance()) + " GNOT** |\n")
	b.WriteString("| Paid out | " + gnot(totalSent) + " GNOT over " +
		strconv.FormatInt(sentCount, 10) + " request(s) |\n")
	b.WriteString("| Open requests | " + strconv.FormatInt(pendingN, 10) + " |\n")
	b.WriteString("| Refused | " + strconv.FormatInt(deniedCount, 10) + " |\n")
	b.WriteString("| Cap per request | " + gnot(maxPerRequest) + " GNOT |\n")
	b.WriteString("| Float address | `" + Address().String() + "` |\n\n")

	b.WriteString("## Open\n\n")
	b.WriteString(table(StatusPending))
	b.WriteString("\n## Decided\n\n")
	b.WriteString(table(""))

	b.WriteString("\n## Approvers\n\n")
	approvers.Iterate("", "", func(k string, _ any) bool {
		b.WriteString("- `" + k + "`\n")
		return false
	})

	b.WriteString("\n" + howto + "\n")
	return b.String()
}

// table lists requests in filing order, keeping only those in `want`, or
// everything already decided when want is empty.
func table(want string) string {
	var rows strings.Builder
	n := 0
	requests.Iterate("", "", func(_ string, v any) bool {
		r := v.(*request)
		if want == "" && r.Status == StatusPending {
			return false
		}
		if want != "" && r.Status != want {
			return false
		}
		n++
		rows.WriteString("| [" + strconv.FormatInt(r.ID, 10) + "](" + Link + ":req/" +
			strconv.FormatInt(r.ID, 10) + ") | `" + r.To.String() + "` | " +
			gnot(r.Amount) + " | " + sanitize.TableCell(excerpt(r.Reason, 60)) + " | " +
			r.Status + " |\n")
		return false
	})
	if n == 0 {
		return "_Nothing here yet._\n"
	}
	return "| # | To | GNOT | Why | State |\n| ---: | --- | ---: | --- | --- |\n" + rows.String()
}

func renderOne(id int64) string {
	r := find(id)
	if r == nil {
		return "# Request " + strconv.FormatInt(id, 10) + "\n\n_No such request._\n"
	}
	var b strings.Builder
	b.WriteString("# Request " + strconv.FormatInt(r.ID, 10) + "\n\n")
	b.WriteString("| | |\n| --- | --- |\n")
	b.WriteString("| To | `" + r.To.String() + "` |\n")
	b.WriteString("| Amount | " + gnot(r.Amount) + " GNOT |\n")
	b.WriteString("| Filed by | `" + r.By.String() + "` |\n")
	b.WriteString("| Filed at height | " + strconv.FormatInt(r.Asked, 10) + " |\n")
	b.WriteString("| State | " + r.Status + " |\n")
	if r.Status != StatusPending {
		b.WriteString("| Decided by | `" + r.Judge.String() + "` |\n")
		b.WriteString("| Decided at height | " + strconv.FormatInt(r.Decided, 10) + " |\n")
	}
	b.WriteString("\n**Why:** " + sanitize.InlineText(r.Reason) + "\n")
	if r.Note != "" {
		b.WriteString("\n**Refused because:** " + sanitize.InlineText(r.Note) + "\n")
	}
	b.WriteString("\n[Back to the faucet](" + Link + ")\n")
	return b.String()
}

// reqPath parses "req/<id>".
func reqPath(path string) (int64, bool) {
	rest, ok := strings.CutPrefix(path, "req/")
	if !ok {
		return 0, false
	}
	id, err := strconv.ParseInt(rest, 10, 64)
	if err != nil || id <= 0 {
		return 0, false
	}
	return id, true
}

// excerpt cuts to width RUNES, never bytes: slicing a multi-byte character in
// half puts invalid UTF-8 on the page, and one emoji in a reason is enough.
// It cuts before escaping, because escaping inserts backslashes and cutting an
// already-escaped string can strand a lone one that escapes the chrome after
// it.
func excerpt(s string, width int) string {
	r := []rune(s)
	if len(r) <= width+1 {
		return s
	}
	return string(r[:width]) + "…"
}

// gnot renders ugnot as GNOT with the trailing zeros of the fraction trimmed,
// so 100000000 reads as 100 and 1500000 as 1.5.
func gnot(ugnot int64) string {
	neg := ""
	if ugnot < 0 {
		neg, ugnot = "-", -ugnot
	}
	whole := strconv.FormatInt(ugnot/1_000_000, 10)
	frac := strconv.FormatInt(ugnot%1_000_000, 10)
	if frac == "0" {
		return neg + whole
	}
	for len(frac) < 6 {
		frac = "0" + frac
	}
	return neg + whole + "." + strings.TrimRight(frac, "0")
}

